<script setup lang="ts">
import {computed,onMounted,onScopeDispose,ref,watch} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import {getAuthContextVersion} from '@/api/http'
import {readLegacyArticleReward,type LegacyArticleReward} from '@/api/legacy/article-reward'
import {useLegacyArticleRewardStore} from '@/stores/legacyArticleReward'
import {useAuthStore} from '@/stores/auth'
const props=defineProps<{articleId:string;initialPrice:number}>(),emit=defineEmits<{contentClick:[event:MouseEvent]}>(),route=useRoute(),auth=useAuthStore(),operations=useLegacyArticleRewardStore()
const mounted=ref(false),state=ref<LegacyArticleReward|null>(null),loading=ref(false),error=ref(''),loggedIn=computed(()=>mounted.value&&!!auth.apiKey&&!!auth.account?.oId)
let sequence=0,readController:AbortController|null=null,purchaseController:AbortController|null=null
const identity=()=>JSON.stringify([getAuthContextVersion(),auth.apiKey,auth.account?.oId,props.articleId,props.initialPrice])
function clear(){sequence++;readController?.abort();readController=null;purchaseController?.abort();purchaseController=null;state.value=null;loading.value=false;error.value=''}
async function load(){if(!loggedIn.value||props.initialPrice<1)return;readController?.abort();const controller=new AbortController();readController=controller;const actor=identity(),run=++sequence,valid=()=>loggedIn.value&&actor===identity()&&run===sequence&&!controller.signal.aborted;state.value=null;loading.value=true;error.value=''
 try{const value=await readLegacyArticleReward(props.articleId,controller.signal);if(valid())state.value=value}catch(e){if(valid())error.value=e instanceof Error?e.message:'打赏状态读取失败'}finally{if(valid()){loading.value=false;readController=null}}
}
async function buy(){if(!loggedIn.value||loading.value||!state.value||state.value.rewarded||state.value.anonymous||state.value.price<1||operations.busy||operations.pending)return;const controller=new AbortController();purchaseController=controller;try{await operations.purchase(props.articleId,controller.signal)}finally{if(purchaseController===controller)purchaseController=null}}
watch(identity,()=>{clear();void load()},{flush:'sync'});watch(()=>operations.lastChange,value=>{if(value.id===props.articleId){clear();void load()}},{flush:'sync'})
onMounted(()=>{mounted.value=true;void load()});onScopeDispose(()=>{mounted.value=false;clear()})
</script>
<template><section v-if="initialPrice>0" class="legacy-reward" aria-label="文章打赏"><h3>🎁 打赏区</h3><template v-if="loggedIn"><p v-if="loading" class="loading-status" role="status">正在读取当前打赏状态…</p><p v-if="state" class="reward-meta">{{ state.price<1?'当前未启用打赏':state.rewarded?'已解锁打赏区':`当前标价 ${state.price} 积分` }}</p><p v-if="state?.anonymous&&!state.rewarded" class="anon-note">旧详情未提供匿名文章的实际解锁费用，当前暂不提供购买。</p><button v-if="state&&!state.rewarded&&!state.anonymous&&state.price>0" type="button" class="reward-buy-btn" :aria-disabled="loading||operations.busy||!!operations.pending" :aria-busy="operations.busy" @click="buy">确认打赏 {{ state.price }} 积分</button><p v-if="operations.pending" role="status">有一笔打赏结果待核对，暂不能再次购买。<RouterLink :to="'/article/'+operations.pending.id">核对原文章</RouterLink></p><button type="button" class="reread-btn" :class="{'is-hidden':state&&!error&&!operations.pending}" :disabled="loading||operations.busy" @click="load">重读打赏状态</button><p v-if="error" role="alert">{{ error }}</p><p v-if="operations.errorId===articleId&&operations.error" role="alert">{{ operations.error }}</p><p v-if="operations.followupError" role="status">{{ operations.followupError }}</p><template v-if="state?.rewarded&&state.price>0&&!loading&&!error"><div v-if="state.html" class="reward-content" v-html="state.html" @click="emit('contentClick',$event)" /><p v-else>打赏区暂无内容</p></template></template><RouterLink v-else :to="{path:'/login',query:{redirect:mounted?route.fullPath:route.fullPath.split('#')[0]}}">登录后查看打赏区</RouterLink></section></template>
<style scoped lang="scss">.legacy-reward{padding:12px 14px;margin:10px 0;border:1px dashed var(--fp-border);border-radius:10px;background:var(--fp-bg);overflow-wrap:anywhere;font-size:13px}h3{margin:0 0 6px;font-size:14px}.loading-status{display:none}.reward-meta{margin:4px 0 8px;color:var(--fp-muted);font-size:12.5px}p{margin:6px 0}button{border:1px solid var(--fp-border);border-radius:999px;padding:5px 14px;font-size:12.5px;color:var(--fp-text);background:var(--fp-card);cursor:pointer;margin:2px 8px 2px 0;transition:border-color .15s,background-color .15s,color .15s}.reward-buy-btn{border-color:var(--fp-primary);color:var(--fp-primary);font-weight:500;&:hover:not([aria-disabled=true]){background:var(--fp-primary-soft,rgba(105,170,105,.12))}}.reread-btn.is-hidden{display:none !important}button[aria-disabled=true],button:disabled{opacity:.5;cursor:default}[role=alert]{color:#c34a36}.reward-content{padding:12px;border:1px solid var(--fp-border);border-radius:8px;background:var(--fp-card)}</style>
